window.refreshMemberOperations=async function(){const host=document.getElementById('member-operations');if(!host)return;host.replaceChildren();const member=WildRideMember.member;if(!member)return;const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e},panel=title=>{const p=el('section',undefined,'ops-panel');p.append(el('h3',title));host.append(p);return p},link=(text,url)=>{const a=el('a',text);a.href=url;return a};try{const [o,a]=await Promise.all([WildRideMember.request('orders'),WildRideMember.request('assessments')]);if(member.role==='admin'){const p=panel('學院管理');p.append(link('進入管理後台 ↗','admin.html'))}const orders=panel('我的訂單與付款紀錄');orders.id='my-orders';orders.append(link('查看購物車 ↗','cart.html'));if(!o.orders.length)orders.append(el('p','尚無訂單，歡迎到馭野嚴選挑選裝備。'));const states={pending:'待確認',processing:'處理中',completed:'已完成',cancelled:'已取消'};for(const r of o.orders){const row=el('div',undefined,'ops-row'),body=el('div',undefined,'grow');body.append(el('b',(r.kind==='inquiry'?'詢價單':'預約單')+' · '+states[r.status]),el('small',r.id),el('p',r.items.map(p=>p.name+' × '+p.quantity).join('、')),el('small','商品參考合計 NT$'+r.total.toLocaleString()+' · '+(r.payment_environment?WildRidePayment.label(r.payment_status)+(r.payment_environment==='stage'?' · 測試交易':''):'未線上收款')));row.append(body);if(r.payment_environment)row.append(link(r.payment_environment==='stage'?'查看測試付款紀錄':'查看付款紀錄','payment-result.html?order='+encodeURIComponent(r.id)));orders.append(row)}const certs=panel('我的教練評量與證書');if(!a.assessments.length)certs.append(el('p','尚無教練評量。技能樹中的自記進度不等同評量通過。'));for(const record of a.assessments){const c=a.certificates.find(c=>c.assessment_id===record.id),r=el('article',undefined,'ops-certificate');if(c&&!c.revoked_at){const img=el('img');img.src=['L1','L2','L3'].includes(c.target)?'assets/levels/'+c.target.toLowerCase()+'.svg':'assets/specialties/'+c.target+'.svg';img.alt=c.target+'認證圖形';r.append(img)}r.append(el('b',record.target+' · '+(record.outcome==='passed'?'教練評量通過':'仍需練習')),el('p',record.test_date+' · 評量教練 '+record.instructor),el('p',record.comment||'無評語'));if(c){r.append(el('small',c.serial));if(c.revoked_at)r.append(el('p','證書已撤銷：'+c.revoked_reason));else r.append(link((WildRideMember.mode==='supabase'?'查看／列印合格證書 ↗':'下載合格證書 PDF ↗'),WildRideMember.certificateUrl(c.id)))}else if(record.outcome==='passed')r.append(el('small','待管理者確認核發證書'));certs.append(r)}const stat=document.getElementById('certificate-stat');if(stat)stat.textContent=a.certificates.filter(c=>!c.revoked_at).length;const statlabel=document.getElementById('certificate-stat-label');if(statlabel)statlabel.textContent='份有效合格證書'}catch(e){host.append(el('p',e.message))}};

